  let pool = unpicked_champions()
  if available(pool, champ_heart_of_ruin()):
    pick(champ_heart_of_ruin())
  elif available(pool, champ_marcella()):
    pick(champ_marcella())
  elif available(pool, champ_cassi_issac()):
    pick(champ_cassi_issac())
  elif available(pool, champ_prism()):
    pick(champ_prism())
  elif available(pool, champ_varg()):
    pick(champ_varg())
  elif available(pool, champ_stellar()):
    pick(champ_stellar())
  elif available(pool, champ_willow()):
    pick(champ_willow())
  else:
    pick(random_champion(pool))
  end_turn()

