  shop()
  end_turn()

if channeling():
  end_turn()

let pos = position()
let home = closest(spawn_region(ally()))
let onspawn = contains(spawn_region(ally()), pos)
if onspawn:
  shop()
  if health() < 0.9 * max_health():
    if enemies_within(4) == 0:
      end_turn()

let foes = enemies_visible()

# Retreat when low on health
if health() < 0.35 * max_health():
  if exists(first(foes)):
    let ct = nearest(foes)
    stun_only(0, ct, unit_position(ct))
    stun_only(1, ct, unit_position(ct))
    move_towards(home)
  else:
    recall()
  end_turn()

# Fight enemy champions
if count(foes) > 0:
  let tgt = weakest(foes)
  let tpos = unit_position(tgt)
  let ls = local_strength(7)
  if ls > 0.8 or unit_health_frac(tgt) < 0.3:
    set_team_target(tgt)
    use_slot(0, tgt, tpos)
    use_slot(1, tgt, tpos)
    let inr = filter(foes, in_attack_range())
    if exists(first(inr)):
      if can_attack():
        attack(weakest(inr))
      if not can_attack():
        if slot_is_reset(0) and ability_ready(0):
          cast_self(0)
          attack(weakest(inr))
        elif slot_is_reset(1) and ability_ready(1):
          cast_self(1)
          attack(weakest(inr))
    else:
      move_towards(tpos)
    end_turn()
  else:
    if distance(pos, tpos) <= 3:
      stun_only(0, tgt, tpos)
      stun_only(1, tgt, tpos)
    move_away_from(tpos)
    end_turn()

