let backline = not (i_am(champ_vendetta()) or i_am(champ_heart_of_ruin()) or i_am(champ_tavi()) or i_am(champ_ryth()))

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
