#   Out of combat, dashes close long distances to camps/altars (fuel-gated).
# - Economy: claim safe gem camps (no golem/monolith), capture, tribute at 40 gems (anything late).

def fight_slot(s, u, d):
    if ability_ready(s):
        if slot_is_stun(s) or slot_is_damage(s) or slot_is_aoe(s):
            if d <= slot_range(s):
                cast_at_unit(s, u)
        elif slot_is_shield(s) or slot_is_heal(s):
            if health() < 0.7 * max_health():
                cast_self(s)

def travel_dash(t):
    if fuel_remaining() > 50000:
        if distance(position(), t) > 4:
            if slot_is_dash(0) and ability_ready(0):
                dash_towards(0, t)
            elif slot_is_dash(1) and ability_ready(1):
