# PLAN (ability-centred team play)
# Roles come from each champion's ability slots, read with slot_* blocks:
#  - STUNNERS (Heart of Ruin dash, Ryth AoE, Tavi, Cassi): open every fight with the stun.
#    A dash closes from range+1, an AoE is cast at the target's tile, a single-target stun at the unit.
#    Heart of Ruin moves first (set_priority) so its stun lands before allies burst.
#  - BURST: non-stun damage or AoE abilities fire only after the stun step (stun before burst).
#  - RESET (Vesper Vale, Vendetta, Tavi, Ryth): basic attack, then cast_self the reset, then attack again.
#  - SUSTAIN: self shields go up when an enemy is within 3. Heals go to the weakest visible ally
#    (below 70%), or to self.
#  - Everyone focuses the team target (set to the weakest visible enemy) when it is within 6 tiles.
#  - Ranged champions kite: step away from an adjacent enemy when hurt.
# Macro play: draft the top-ladder picks, buy Treasure shards then Bruiser Strength, take captures,
# farm rich camps over near ones when only a few tiles farther, tribute 25-gem bags at altars away
# from monoliths, tribute at once when an enemy is near, retreat below 35% HP.
# Tunables: RETREAT_HP 0.35, ENGAGE_RANGE 5, OUTNUMBER margin 2, BAG 25, RICH_DETOUR 6.

def shop(g):
    if gold() >= 30:
        if round_number() < 400:
            buy(shard_of(family_treasure(), stat_strength()), floor(gold() / 30))
        else:
            buy(shard_of(family_bruiser(), stat_strength()), floor(gold() / 30))

def go_tribute(a):
    if distance(position(), a) <= 1:
        tribute(a)
    else:
        move_towards(a)
    end_turn()

def fight(t, wk):
    # 1. stun opener
    if ability_ready(0) and slot_stun(0) > 0 and distance(position(), unit_position(t)) <= slot_range(0) + 1:
        if slot_is_dash(0):
            dash_towards(0, unit_position(t))
        elif distance(position(), unit_position(t)) <= slot_range(0):
            if slot_radius(0) > 0:
                cast_at_tile(0, unit_position(t))
            else:
                cast_at_unit(0, t)
    if ability_ready(1) and slot_stun(1) > 0 and distance(position(), unit_position(t)) <= slot_range(1) + 1:
        if slot_is_dash(1):
            dash_towards(1, unit_position(t))
        elif distance(position(), unit_position(t)) <= slot_range(1):
            if slot_radius(1) > 0:
                cast_at_tile(1, unit_position(t))
            else:
                cast_at_unit(1, t)
    # 2. burst after the stun
    if ability_ready(0) and slot_stun(0) == 0 and distance(position(), unit_position(t)) <= slot_range(0):
        if slot_is_damage(0):
            cast_at_unit(0, t)
        elif slot_is_aoe(0):
            cast_at_tile(0, unit_position(t))
    if ability_ready(1) and slot_stun(1) == 0 and distance(position(), unit_position(t)) <= slot_range(1):
        if slot_is_damage(1):
            cast_at_unit(1, t)
        elif slot_is_aoe(1):
            cast_at_tile(1, unit_position(t))
    # 3. sustain
    if ability_ready(0) and slot_is_shield(0) and enemies_within(3) > 0:
        cast_self(0)
    if ability_ready(1) and slot_is_shield(1) and enemies_within(3) > 0:
        cast_self(1)
    if ability_ready(0) and slot_is_heal(0):
        if exists(wk) and unit_health_frac(wk) < 0.7:
            cast_at_unit(0, wk)
        elif health() < 0.6 * max_health():
            cast_self(0)
    if ability_ready(1) and slot_is_heal(1):
        if exists(wk) and unit_health_frac(wk) < 0.7:
            cast_at_unit(1, wk)
        elif health() < 0.6 * max_health():
            cast_self(1)
    # 4. move and basic attack
    if i_am_ranged():
        if distance(position(), unit_position(t)) > 3:
            move_towards(unit_position(t))
        elif distance(position(), unit_position(t)) <= 1 and health() < 0.7 * max_health():
            move_away_from(unit_position(t))
        else:
            attack(t)
    else:
        if distance(position(), unit_position(t)) > 1:
            if ability_ready(0) and slot_is_dash(0) and slot_stun(0) == 0 and distance(position(), unit_position(t)) <= slot_range(0) + 1:
                dash_towards(0, unit_position(t))
            elif ability_ready(1) and slot_is_dash(1) and slot_stun(1) == 0 and distance(position(), unit_position(t)) <= slot_range(1) + 1:
                dash_towards(1, unit_position(t))
            if distance(position(), unit_position(t)) > 1:
                move_towards(unit_position(t))
        attack(t)
    # 5. reset after a basic, then attack again
    if not can_attack():
        if ability_ready(0) and slot_is_reset(0):
            cast_self(0)
            attack(t)
        elif ability_ready(1) and slot_is_reset(1):
            cast_self(1)
            attack(t)
    end_turn()

