# PLAN (abilities-first champion):
# - Draft the top-team roster: Vesper Vale, Heart of Ruin, Marcella, Vendetta, Ryth.
# - Each champion fights with a fixed ability script per turn:
#   1. OPENER: any stun ability (or dash) is fired first. A dash goes along the path,
#      an area ability (radius > 0) is cast at the target's tile, otherwise at the unit.
#   2. Close in (melee to 1, ranged to 3), then basic attack.
#   3. RESET: if the slot is an attack reset and we just attacked, cast it on ourselves,
#      then attack again.
#   4. BURST: non-stun damage or area abilities follow, after the stun has landed.
#   5. Shields and heals are self-cast when hurt in a fight.
# - Focus fire: use the team target if visible and near, else the nearest enemy, and
#   publish it as the team target.
# - Low HP: step away while in danger, recall only when safe.
# - Farm: capture cleared camps and hit camps in range (also with damage abilities).
#   Walk to the nearest camp, or a rich (15+ gem) camp if it is only slightly farther.
#   Monoliths are skipped. Tribute big bags at altars away from monoliths.

def fight(t):
    let fd = distance(position(), unit_position(t))
    set_team_target(t)
    # opener: stun or dash first
    if ability_ready(0) and (slot_stun(0) > 0 or slot_is_dash(0)):
        if slot_is_dash(0):
            if fd <= slot_range(0) + 1 and fd > 1:
                dash_towards(0, unit_position(t))
        elif slot_radius(0) > 0:
            if fd <= slot_range(0) + slot_radius(0):
                cast_at_tile(0, unit_position(t))
        elif fd <= slot_range(0):
            cast_at_unit(0, t)
    if ability_ready(1) and (slot_stun(1) > 0 or slot_is_dash(1)):
        if slot_is_dash(1):
            if fd <= slot_range(1) + 1 and fd > 1:
                dash_towards(1, unit_position(t))
        elif slot_radius(1) > 0:
            if fd <= slot_range(1) + slot_radius(1):
                cast_at_tile(1, unit_position(t))
        elif fd <= slot_range(1):
            cast_at_unit(1, t)
    # approach
    if i_am_ranged():
        if distance(position(), unit_position(t)) > 3 and can_move():
            move_towards(unit_position(t))
    else:
        if distance(position(), unit_position(t)) > 1 and can_move():
            move_towards(unit_position(t))
    attack(t)
    # reset after a basic, then attack again
    if ability_ready(0) and slot_is_reset(0) and not can_attack():
        cast_self(0)
        attack(t)
    if ability_ready(1) and slot_is_reset(1) and not can_attack():
        cast_self(1)
        attack(t)
    # burst after the stun
    if ability_ready(0) and slot_stun(0) == 0 and (slot_is_damage(0) or slot_is_aoe(0)):
        if slot_radius(0) > 0:
            if distance(position(), unit_position(t)) <= slot_range(0) + slot_radius(0):
                cast_at_tile(0, unit_position(t))
        elif distance(position(), unit_position(t)) <= slot_range(0):
            cast_at_unit(0, t)
    if ability_ready(1) and slot_stun(1) == 0 and (slot_is_damage(1) or slot_is_aoe(1)):
        if slot_radius(1) > 0:
            if distance(position(), unit_position(t)) <= slot_range(1) + slot_radius(1):
                cast_at_tile(1, unit_position(t))
        elif distance(position(), unit_position(t)) <= slot_range(1):
            cast_at_unit(1, t)
    # sustain
    if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)) and health() < 0.85 * max_health():
        cast_self(0)
    if ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)) and health() < 0.85 * max_health():
        cast_self(1)

